function App() {
  const files = [
    'app/page.tsx',
    'app/about/page.tsx',
    'app/(marketing)/pricing/page.tsx',
    'app/blog/[slug]/page.tsx',
  ];
  const toUrl = (f) => {
    const parts = f.replace('app', '').replace('/page.tsx', '')
      .split('/').filter(Boolean)
      .filter(p => !(p.startsWith('(') && p.endsWith(')')))
      .map(p => (p.startsWith('[') ? ':' + p.slice(1, -1) : p));
    return '/' + parts.join('/');
  };
  return (
    <table style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 12 }}>
      <tbody>
        {files.map(f => (
          <tr key={f}><td style={{ paddingRight: 16 }}>{f}</td><td>{toUrl(f)}</td></tr>
        ))}
      </tbody>
    </table>
  );
}

