function App() {
  const map = {
    'app/page.tsx': '/',
    'app/team/page.tsx': '/team',
    'app/(shop)/cart/page.tsx': '/cart (group stripped)',
    'app/products/[id]/page.tsx': '/products/:id (dynamic)',
  };
  return (
    <ul style={{ fontFamily: 'system-ui', padding: 16 }}>
      {Object.entries(map).map(([k, v]) => <li key={k}><code>{k}</code> -> {v}</li>)}
    </ul>
  );
}
